// Merge OSV (severity/cvss/summary) with the repo's vulnerable_functions.json
// fallback (function-level reachability data). See prompts/security_agent.md.
const ghsaId = $('When Executed by Another Workflow').first().json.ghsa_id;
const osv = $('Fetch OSV.dev advisory').first().json || {};
// Fetched as text (raw media type), so it arrives as a string in .data and
// has to be parsed. Unparseable or unreachable -> no fallback, never a crash.
let fallbackRaw = $('Fetch fallback config').first().json || {};
if (typeof fallbackRaw.data === 'string') {
  try { fallbackRaw = JSON.parse(fallbackRaw.data); } catch (e) { fallbackRaw = {}; }
}

const severity = (osv.severity && osv.severity[0] && osv.severity[0].score) ? osv.severity[0].score
  : (osv.database_specific && osv.database_specific.severity) || null;

let vulnerableFunctions = [];
let source = 'none';
const packages = fallbackRaw.packages || {};
for (const pkgName of Object.keys(packages)) {
  const entry = packages[pkgName];
  if (ghsaId && String(entry.ghsa_id || '').toUpperCase() === String(ghsaId).toUpperCase()) {
    vulnerableFunctions = entry.vulnerable_functions || [];
    source = 'config';
    break;
  }
}

return [{
  json: {
    ghsa_id: ghsaId,
    cve_id: (osv.aliases || []).find((a) => a.startsWith('CVE-')) || null,
    severity: severity,
    summary: osv.summary || osv.details || null,
    vulnerable_functions: vulnerableFunctions,
    source: source,
    osv_url: `https://osv.dev/vulnerability/${ghsaId}`
  }
}];
